import{_ as a,o as s,c as t,ai as o,aj as n,ak as l,al as i}from"./chunks/framework.Ba-VnP44.js";const k=JSON.parse('{"title":"ModelDesk · 本机多模态 AI 配测台","description":"","frontmatter":{"title":"ModelDesk · 本机多模态 AI 配测台","outline":"deep"},"headers":[],"relativePath":"apps/ai/modeldesk.md","filePath":"apps/ai/modeldesk.md"}'),r={name:"apps/ai/modeldesk.md"};function d(p,e,c,h,g,b){return s(),t("div",null,[...e[0]||(e[0]=[o('<h1 id="modeldesk-·-本机多模态-ai-配测台" tabindex="-1">ModelDesk · 本机多模态 AI 配测台 <a class="header-anchor" href="#modeldesk-·-本机多模态-ai-配测台" aria-label="Permalink to “ModelDesk · 本机多模态 AI 配测台”">​</a></h1><blockquote><p><strong>项目状态</strong>：已发布（GitHub Release v0.2.1 安装包；源码 0.2.3）· 可运行验证已完成（本地 install / unit / smoke / build 全部通过） 角色：项目作者 / 全栈开发。这是一个面向开发者的本机工具，不是聊天产品。</p></blockquote><p>ModelDesk 把「配置模型 → 测试模型 → 对比模型 → 选用模型 → 接入应用」这条链路收进一个本机配测台：一处配置 Text / Image / Audio / Video 相关 API，用相同输入并行对比 2～3 个模型，查看输出、延迟、TTFT、Token 与错误信息，点击 <strong>Use this model</strong> 复制 curl / Python / Java，通过本机 OpenAI 兼容网关 <code>:3300/v1</code> 接入自己的程序。</p><ul><li>仓库：<a href="https://github.com/gao-shu/modeldesk" target="_blank" rel="noreferrer">https://github.com/gao-shu/modeldesk</a>（MIT）</li><li>安装包：<a href="https://github.com/gao-shu/modeldesk/releases" target="_blank" rel="noreferrer">https://github.com/gao-shu/modeldesk/releases</a></li></ul><p><img src="'+n+'" alt="ModelDesk 模型配置页" loading="lazy"><img src="'+l+`" alt="ModelDesk 图片实测" loading="lazy"></p><h2 id="一、项目背景与解决的问题" tabindex="-1">一、项目背景与解决的问题 <a class="header-anchor" href="#一、项目背景与解决的问题" aria-label="Permalink to “一、项目背景与解决的问题”">​</a></h2><p><strong>使用场景</strong>：开发者同时用多家模型的 API（OpenAI / 火山 / 智谱 / 本地 Ollama 等）。厂商控制台适合测单个模型，但要对比多家接口，往往要在多个后台、多套 Key、多种返回格式之间来回切换，最后还得手工改调用代码接到业务里。</p><p><strong>要解决的具体问题</strong>：</p><ul><li>一处配置、统一保存多家模型与加密 Key；</li><li>同一输入并行对比 2～3 个模型，并排看结果、延迟、Token；</li><li>选中模型后直接生成可复制的调用代码；</li><li>通过本机 OpenAI 兼容网关，让业务代码只打一个 <code>/v1</code>，不直连各家厂商。</li></ul><p><strong>目标用户</strong>：需要用多个模型、做选型与接入的开发者（不是终端消费者）。</p><h2 id="二、项目状态" tabindex="-1">二、项目状态 <a class="header-anchor" href="#二、项目状态" aria-label="Permalink to “二、项目状态”">​</a></h2><table tabindex="0"><thead><tr><th>项目</th><th>说明</th></tr></thead><tbody><tr><td>当前阶段</td><td>已发布（Windows 安装包 v0.2.1；源码 0.2.3）</td></tr><tr><td>完成度</td><td>核心链路（配置 / Playground / Compare / Use / Gateway / MCP）可用</td></tr><tr><td>最后更新</td><td>2026-10-22</td></tr><tr><td>可访问地址</td><td>GitHub Release 提供安装包；源码可 <code>pnpm dev</code> 本地运行</td></tr><tr><td>可运行验证</td><td>✅ 已完成（见第七节）：<code>pnpm install</code> / <code>test:unit</code> 93 测全过 / <code>smoke</code> 2/2 / <code>build</code> 成功</td></tr></tbody></table><blockquote><p><strong>诚实说明</strong>：本页「构建 / 单元测试 / 冒烟 / 生产构建」由我在本地独立完成、<strong>可复现</strong>（单测日志留存，其余以产物与脚本为证）；「调用真实模型返回结果」需用户自备 API Key，我<strong>未</strong>用任何真实外部模型 Key 跑通业务数据，相关功能以官方文档与本地无 Key 路径（页面渲染、网关契约、单测）为证。</p></blockquote><h2 id="三、个人承担的工作" tabindex="-1">三、个人承担的工作 <a class="header-anchor" href="#三、个人承担的工作" aria-label="Permalink to “三、个人承担的工作”">​</a></h2><ul><li>产品定位与范围冻结（Positioning / Product Freeze）：明确「Test. Compare. Use.」主线，划清不做 SaaS / 多租户 / Agent 编排平台。</li><li>整体架构与模块拆分：Web（Next）界面 + 同进程 Gateway <code>/v1</code> + <code>packages/run-core</code> 编排 + <code>adapters</code> 适配器 + <code>model-registry</code> 注册表 + <code>object-storage</code> / <code>tos-storage</code>。</li><li>网关与 MCP 接入设计：OpenAI 兼容 <code>/v1</code> 契约、别名机制、Cursor/MCP 配置导出。</li><li>本地优先与安全：API Key 落盘加密、默认仅监听 localhost、无登录无云同步。</li><li>工程化：pnpm monorepo、Docker / docker-compose、GitHub Actions、SECURITY.md、CHANGELOG、OSS 发布检查脚本。</li></ul><h2 id="四、技术栈与架构" tabindex="-1">四、技术栈与架构 <a class="header-anchor" href="#四、技术栈与架构" aria-label="Permalink to “四、技术栈与架构”">​</a></h2><ul><li><strong>前端 / 界面</strong>：Next.js（apps/web），Playground / Compare / Models / Settings / History。</li><li><strong>网关</strong>：OpenAI 兼容 HTTP（<code>:3300/v1</code>，与 Web 同进程；可选无头 <code>:3310</code>）。</li><li><strong>核心编排</strong>：<code>packages/run-core</code>（run 编排、并发、部分失败保留）。</li><li><strong>适配器</strong>：<code>packages/adapters</code>（对接各厂商 / 协议）。</li><li><strong>模型注册表</strong>：<code>packages/model-registry</code>（配置名 ↔ 网关 model id 映射、别名）。</li><li><strong>存储</strong>：<code>packages/object-storage</code> + <code>packages/tos-storage</code>（产物 / 对象存储，按需公网 URL）。</li><li><strong>共享</strong>：<code>packages/shared</code>（导航、类型）、<code>packages/gateway-client</code>（TS 客户端）。</li><li><strong>桌面端</strong>：apps/desktop（Tauri 壳，需 Rust）。</li><li><strong>数据</strong>：SQLite + 加密后的 Key，默认仓库 <code>data/</code>（开发）或系统数据目录。</li></ul><div class="language-text line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>界面（Playground · Compare · Models）</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>   packages/run-core</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span> 适配器（adapters）+ 模型注册表</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span> 加密后的 API Key / SQLite（数据目录）</span></span>
<span class="line"><span></span></span>
<span class="line"><span>界面 ──► OpenAI 兼容网关（:3300/v1）</span></span>
<span class="line"><span>              ↓</span></span>
<span class="line"><span>     自己的应用 / 脚本 / Cursor / MCP / CLI</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br></div></div><h2 id="五、核心功能与关键实现" tabindex="-1">五、核心功能与关键实现 <a class="header-anchor" href="#五、核心功能与关键实现" aria-label="Permalink to “五、核心功能与关键实现”">​</a></h2><h3 id="_1-playground-单模型实测" tabindex="-1">1. Playground（单模型实测） <a class="header-anchor" href="#_1-playground-单模型实测" aria-label="Permalink to “1. Playground（单模型实测）”">​</a></h3><p>分别测试 Text / Image / Audio / Video，一次测一个模型（<code>/runs/text</code>、<code>/runs/image</code> 等）。实现上由 <code>run-core</code> 统一封装「构造请求 → 调适配器 → 收集延迟/TTFT/Token/错误」。</p><h3 id="_2-compare-同输入并行对比" tabindex="-1">2. Compare（同输入并行对比） <a class="header-anchor" href="#_2-compare-同输入并行对比" aria-label="Permalink to “2. Compare（同输入并行对比）”">​</a></h3><p><code>/runs/compare</code> 用相同输入并行运行 2～3 个同模态模型，各列独立展示结果与指标；<strong>某一路失败不影响其他路</strong>。复杂度在并发编排与「部分失败保留」——这也正是 <code>run-core</code> 单测重点覆盖的路径（<code>creates 3 jobs and finalizes as partial when one fails</code> 等）。</p><h3 id="_3-use-this-model-生成调用代码" tabindex="-1">3. Use this model（生成调用代码） <a class="header-anchor" href="#_3-use-this-model-生成调用代码" aria-label="Permalink to “3. Use this model（生成调用代码）”">​</a></h3><p>在对比结果卡片上点击，复制面向本机网关的 curl / Python / Java 示例；系统设置里也提供 Gateway / MCP 片段。</p><h3 id="_4-本地-openai-兼容网关" tabindex="-1">4. 本地 OpenAI 兼容网关 <a class="header-anchor" href="#_4-本地-openai-兼容网关" aria-label="Permalink to “4. 本地 OpenAI 兼容网关”">​</a></h3><p>业务只打 <code>http://127.0.0.1:3300/v1</code>，<code>model</code> 可填稳定别名、台账 UUID 或唯一配置名；上游 Key 只用 Desk 里已保存的，请求里即使带 Key 也不会被用来调厂商。契约见仓库 <code>apps/web/public/openapi.yaml</code>（运行时亦可访问 <code>http://127.0.0.1:3300/openapi.yaml</code>）。</p><h2 id="六、运行截图或演示" tabindex="-1">六、运行截图或演示 <a class="header-anchor" href="#六、运行截图或演示" aria-label="Permalink to “六、运行截图或演示”">​</a></h2><p>均为仓库内真实截图（非示意图）；模型配置页与图片实测见本节开头两张，结果画廊如下：</p><p><img src="`+i+`" alt="ModelDesk 结果画廊" loading="lazy"></p><blockquote><p>演示视频仍在准备中；完整链路（测试 → 对比 → 查看 → 使用当前模型 → curl/Python/Java → 本地网关）当前版本已支持。</p></blockquote><h2 id="七、测试与部署说明" tabindex="-1">七、测试与部署说明 <a class="header-anchor" href="#七、测试与部署说明" aria-label="Permalink to “七、测试与部署说明”">​</a></h2><p><strong>本地运行方式</strong>：</p><div class="language-bash line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">          # Node 22 + pnpm 9.15.0</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .env.example</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> apps/web/.env.local</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dev</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">              # http://127.0.0.1:3300</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p><strong>测试范围与结果（本人本地实测，2026-10-22）</strong>：</p><table tabindex="0"><thead><tr><th>命令</th><th>结果</th></tr></thead><tbody><tr><td><code>pnpm install</code></td><td>619 包，52.8s，成功</td></tr><tr><td><code>pnpm test:unit</code></td><td>4 个包共 <strong>93 测全过</strong>（run-core 31 / adapters 36 / object-storage 20 / tos-storage 6），0 失败</td></tr><tr><td><code>pnpm smoke</code></td><td><strong>2/2 通过</strong>（web.home、web.models 均 200）</td></tr><tr><td><code>pnpm build</code></td><td>生产构建成功，产出 <code>/models</code>、<code>/runs/compare</code>、<code>/v1/[...path]</code>、<code>/healthz</code> 等路由</td></tr></tbody></table><p><strong>部署方式</strong>：Docker / docker-compose 本机部署（见 <code>docs/deploy-baota.md</code>）；GitHub Actions 负责构建与发版检查。桌面端经 Tauri 打 Windows / macOS 安装包。</p><h2 id="八、github-仓库" tabindex="-1">八、GitHub 仓库 <a class="header-anchor" href="#八、github-仓库" aria-label="Permalink to “八、GitHub 仓库”">​</a></h2><ul><li>仓库地址：<a href="https://github.com/gao-shu/modeldesk" target="_blank" rel="noreferrer">https://github.com/gao-shu/modeldesk</a></li><li>许可证：MIT（见 <code>LICENSE</code>）</li><li>第三方依赖与原创边界：本项目为作者原创的本地工具；若后续接入任何上游 SDK，会在 <code>docs/adapters</code> 与 NOTICE 中明确标注。</li></ul><h2 id="九、相关技术文章" tabindex="-1">九、相关技术文章 <a class="header-anchor" href="#九、相关技术文章" aria-label="Permalink to “九、相关技术文章”">​</a></h2><ul><li><a href="/my-vitepress-site/ai/creation/modeldesk-architecture.html">ModelDesk 架构解析：把多个模型 API 收敛成本地一个 /v1 网关</a></li></ul><hr><blockquote><p>本页所有「可运行 / 可验证」结论均来自本人本地复现；未使用真实模型 Key 跑业务数据，相关能力以官方文档与无 Key 路径为证，不夸大、不虚构。</p></blockquote>`,43)])])}const u=a(r,[["render",d]]);export{k as __pageData,u as default};
